const PRCL_BASE = "default-src 'none'; style-src 'self'; img-src 'self'; font-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'";
const PRCL_SCRIPT = "default-src 'none'; style-src 'self'; script-src 'self'; img-src 'self'; font-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'";
const PRCL_WORKER = "default-src 'self'; connect-src 'self'";

function prclPort():int{$s=stream_socket_server('tcp://127.0.0.1:0',$e,$m);if($s===false)throw new TestFailure('setup: allocate port');$n=(string)stream_socket_get_name($s,false);fclose($s);return(int)substr($n,strrpos($n,':')+1);}
function prclStart(int $port,string $prefix):array{$env=['FMONITOR_DB_HOST'=>getenv('FMONITOR_DB_HOST')?:'mariadb','FMONITOR_DB_PORT'=>getenv('FMONITOR_DB_PORT')?:'3306','FMONITOR_DB_NAME'=>getenv('FMONITOR_DB_NAME')?:'fmonitor2_test','FMONITOR_DB_USER'=>getenv('FMONITOR_DB_USER')?:'fmonitor2_test','FMONITOR_DB_PASSWORD'=>getenv('FMONITOR_DB_PASSWORD')?:'fmonitor2_test_local','FMONITOR_PROCESS_TABLE_PREFIX'=>$prefix];$cmd=[PHP_BINARY,'-d','expose_php=0','-S','127.0.0.1:'.$port,dirname(__DIR__,2).'/rapid-pilot/router.php'];$p=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2),$env);if(!is_resource($p))throw new TestFailure('setup: start login server');fclose($pipes[0]);stream_set_blocking($pipes[1],false);stream_set_blocking($pipes[2],false);$until=microtime(true)+5;while(microtime(true)<$until){$s=@stream_socket_client("tcp://127.0.0.1:$port",$e,$m,.1);if($s!==false){fclose($s);return compact('p','pipes');}usleep(20000);}throw new TestFailure('setup: login server did not listen');}
function prclStop(?array $server):void{if($server===null||!is_resource($server['p']))return;if(proc_get_status($server['p'])['running'])proc_terminate($server['p']);foreach([1,2]as$i)if(is_resource($server['pipes'][$i])){stream_get_contents($server['pipes'][$i]);fclose($server['pipes'][$i]);}proc_close($server['p']);}
function prclRequest(int $port,string $method,string $path,string $body='',string $cookie=''):array{$s=stream_socket_client("tcp://127.0.0.1:$port",$e,$m,5);if($s===false)throw new TestFailure('setup: connect login server');$headers="$method $path HTTP/1.1\r\nHost: login.example.test\r\nConnection: close\r\n";if($cookie!=='')$headers.="Cookie: $cookie\r\n";if($body!=='')$headers.="Content-Type: application/x-www-form-urlencoded\r\n";$headers.='Content-Length: '.strlen($body)."\r\n\r\n";fwrite($s,$headers.$body);stream_socket_shutdown($s,STREAM_SHUT_WR);$raw='';while(!feof($s))$raw.=(string)fread($s,65536);fclose($s);[$head,$bytes]=array_pad(explode("\r\n\r\n",$raw,2),2,'');$lines=explode("\r\n",$head);preg_match('/^HTTP\/\d\.\d (\d{3})/',(string)array_shift($lines),$match);$parsed=[];foreach($lines as$line)if(str_contains($line,':')){[$name,$value]=explode(':',$line,2);$parsed[strtolower(trim($name))][]=trim($value);}return['status'=>(int)($match[1]??0),'headers'=>$parsed,'body'=>$bytes];}
function prclHeader(array $response,string $name):?string{$values=$response['headers'][strtolower($name)]??[];return count($values)===1?$values[0]:null;}
function prclCookie(array $response):string{$raw=prclHeader($response,'set-cookie');if($raw===null||preg_match('/^([^;]+)/',$raw,$m)!==1)throw new TestFailure('setup: login cookie missing');return$m[1];}
function prclCsrf(array $response):string{if(preg_match('/name="csrfToken" value="([0-9a-f]{64})"/',$response['body'],$m)!==1)throw new TestFailure('setup: login CSRF missing');return$m[1];}
function prclExpect(array &$failures,string $scenario,array $response,int $status,string $csp,?string $location=null):void{if($response['status']!==$status){$failures[]="$scenario setup/status: expected $status, actual {$response['status']}";return;}$actual=prclHeader($response,'content-security-policy');if($actual!==$csp)$failures[]="$scenario CSP: expected [$csp], actual [".($actual??'missing').']';foreach(['unsafe-inline','unsafe-eval','nonce-','sha256-','sha384-','sha512-','*','http:','https:']as$token)if(is_string($actual)&&str_contains($actual,$token))$failures[]="$scenario CSP contains forbidden token $token";if(prclHeader($response,'cache-control')!=='no-store')$failures[]="$scenario cache-control changed";if($location!==null&&prclHeader($response,'location')!==$location)$failures[]="$scenario location changed";if(prclHeader($response,'content-length')!==null&&prclHeader($response,'content-length')!==(string)strlen($response['body']))$failures[]="$scenario content-length changed";}
function prclSafeHtml(array &$failures,string $scenario,string $html):void{if(preg_match('#<script(?![^>]+\bsrc="/pilot/)[^>]*>#i',$html)===1)$failures[]="$scenario has inline/non-local script";if(preg_match('/\son[a-z]+\s*=/i',$html)===1)$failures[]="$scenario has inline event attribute";if(preg_match('/(?:href|src)\s*=\s*["\']\s*javascript:/i',$html)===1)$failures[]="$scenario has javascript URL";if(preg_match('/\b(?:eval|Function)\s*\(/',$html)===1)$failures[]="$scenario has executable string evaluation";if(preg_match('#<script[^>]+src=["\'](?:https?:)?//#i',$html)===1)$failures[]="$scenario has third-party script";}
function prclAsset(array &$failures,string $scenario,array $response,string $sourcePath,array $expectedHeaders,string $csp):void{$bytes=file_get_contents($sourcePath);if(!is_string($bytes))throw new TestFailure("setup: unreadable independent asset source $sourcePath");if($response['status']!==200){$failures[]="$scenario setup/status: expected 200, actual {$response['status']}";return;}if(!hash_equals(hash('sha256',$bytes),hash('sha256',$response['body'])))$failures[]="$scenario bytes differ from independent source fixture";foreach($expectedHeaders+['content-length'=>(string)strlen($bytes)]as$name=>$value)if(prclHeader($response,$name)!==$value)$failures[]="$scenario exact header $name changed";$actual=prclHeader($response,'content-security-policy');if($actual!==$csp)$failures[]="$scenario CSP: expected [$csp], actual [".($actual??'missing').']';}

$db=new mysqli(getenv('FMONITOR_DB_HOST')?:'mariadb',getenv('FMONITOR_DB_USER')?:'fmonitor2_test',getenv('FMONITOR_DB_PASSWORD')?:'fmonitor2_test_local',getenv('FMONITOR_DB_NAME')?:'fmonitor2_test',(int)(getenv('FMONITOR_DB_PORT')?:3306));$db->set_charset('utf8mb4');$token=bin2hex(random_bytes(5));$prefix='prcl_'.$token.'_';$tables=['fm2_pilot_auth_attempts','fm2_pilot_auth_credentials','fm2_pilot_users'];$server=null;
try{
 $db->query("CREATE TABLE `{$prefix}fm2_pilot_users`(user_id BIGINT PRIMARY KEY,email VARCHAR(255) NOT NULL,full_name VARCHAR(255) NOT NULL,status TINYINT NOT NULL,activation_state VARCHAR(32) NOT NULL)");
 $db->query("CREATE TABLE `{$prefix}fm2_pilot_auth_credentials`(user_id BIGINT PRIMARY KEY,email_normalized VARCHAR(255) NOT NULL,password_hash VARCHAR(255) NULL)");
 $db->query("CREATE TABLE `{$prefix}fm2_pilot_auth_attempts`(id BIGINT AUTO_INCREMENT PRIMARY KEY,email_normalized VARCHAR(255) NOT NULL,succeeded TINYINT NOT NULL,attempted_at DATETIME(6) NOT NULL)");
 $email='login.fixture@shlz.ru';$password='Correct fixture password 2026';$hash=password_hash($password,PASSWORD_ARGON2ID);if(!is_string($hash))throw new TestFailure('setup: password hash');$s=$db->prepare("INSERT INTO `{$prefix}fm2_pilot_users` VALUES(17,?,?,1,'active')");$name='Тестовый Пользователь';$s->bind_param('ss',$email,$name);$s->execute();$s=$db->prepare("INSERT INTO `{$prefix}fm2_pilot_auth_credentials` VALUES(17,?,?)");$s->bind_param('ss',$email,$hash);$s->execute();
 $port=prclPort();$server=prclStart($port,$prefix);$failures=[];
 $root=dirname(__DIR__,2);prclAsset($failures,'A6 CSS asset',prclRequest($port,'GET','/pilot/assets/pilot.css'),$root.'/rapid-pilot/pilot.css',['content-type'=>'text/css; charset=UTF-8','cache-control'=>'no-store','x-content-type-options'=>'nosniff'],PRCL_BASE);
 prclAsset($failures,'A6 SVG asset',prclRequest($port,'GET','/pilot/assets/favicon.svg'),$root.'/rapid-pilot/favicon.svg',['content-type'=>'image/svg+xml; charset=UTF-8','cache-control'=>'public, max-age=31536000, immutable','x-content-type-options'=>'nosniff'],PRCL_BASE);
 prclAsset($failures,'A6 font asset',prclRequest($port,'GET','/pilot/assets/fonts/golos-text-cyrillic-400-normal.woff2'),$root.'/rapid-pilot/fonts/golos-text-cyrillic-400-normal.woff2',['content-type'=>'font/woff2','cache-control'=>'public, max-age=31536000, immutable','x-content-type-options'=>'nosniff'],PRCL_BASE);
 prclAsset($failures,'A6 Service Worker asset',prclRequest($port,'GET','/pilot/assets/checklist-sw.js'),$root.'/app/PilotHttp/checklist-sw.js',['content-type'=>'text/javascript; charset=UTF-8','cache-control'=>'no-store','x-content-type-options'=>'nosniff','service-worker-allowed'=>'/pilot/'],PRCL_WORKER);
 $get=prclRequest($port,'GET','/pilot/login');$cookie=prclCookie($get);$csrf=prclCsrf($get);prclExpect($failures,'A1 scripted GET login',$get,200,PRCL_SCRIPT);prclSafeHtml($failures,'A1 login final HTML',$get['body']);
 $invalidBody=http_build_query(['csrfToken'=>$csrf,'email'=>'missing.fixture@shlz.ru']);$invalid=prclRequest($port,'POST','/pilot/login',$invalidBody,$cookie);prclExpect($failures,'A1b successful scripted POST login 200',$invalid,200,PRCL_SCRIPT);prclSafeHtml($failures,'A1b login POST final HTML',$invalid['body']);
 if(!str_contains($invalid['body'],'/pilot/assets/preloader.js'))$failures[]='A2 POST login body lost external preloader';
 $error=prclRequest($port,'POST','/pilot/login',http_build_query(['csrfToken'=>'wrong','email'=>$email]),$cookie);prclExpect($failures,'A4 login error 403',$error,403,PRCL_BASE);
 $validBody=http_build_query(['csrfToken'=>$csrf,'email'=>$email,'password'=>$password]);$redirect=prclRequest($port,'POST','/pilot/login',$validBody,$cookie);prclExpect($failures,'A5 successful login redirect 303',$redirect,303,PRCL_BASE,'/pilot/objects');
 if($failures!==[])throw new TestFailure("PILOT-ROUTE-CSP-001 login intended RED (fixture reached HTTP outcomes):\n- ".implode("\n- ",$failures));
 echo "pilot_route_csp_login_001_test: PASS\n";
}finally{prclStop($server);foreach($tables as$table)$db->query("DROP TABLE IF EXISTS `{$prefix}{$table}`");$db->close();}
